class MessageRole(enum.Enum):
    
    USER = 0
    
    ASSISTANT = 1
    
    TOOL = 2
    


class _UniffiFfiConverterTypeMessageRole(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return MessageRole.USER
        if variant == 2:
            return MessageRole.ASSISTANT
        if variant == 3:
            return MessageRole.TOOL
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == MessageRole.USER:
            return
        if value == MessageRole.ASSISTANT:
            return
        if value == MessageRole.TOOL:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == MessageRole.USER:
            buf.write_i32(1)
        if value == MessageRole.ASSISTANT:
            buf.write_i32(2)
        if value == MessageRole.TOOL:
            buf.write_i32(3)



class _UniffiFfiConverterString:
    @staticmethod
    def check_lower(value):
        if not isinstance(value, str):
            raise TypeError("argument must be str, not {}".format(type(value).__name__))
        return value

    @staticmethod
    def read(buf):
        size = buf.read_i32()
        if size < 0:
            raise InternalError("Unexpected negative string length")
        utf8_bytes = buf.read(size)
        return utf8_bytes.decode("utf-8")

    @staticmethod
    def write(value, buf):
        utf8_bytes = value.encode("utf-8")
        buf.write_i32(len(utf8_bytes))
        buf.write(utf8_bytes)

    @staticmethod
    def lift(buf):
        with buf.consume_with_stream() as stream:
            return stream.read(stream.remaining()).decode("utf-8")

    @staticmethod
    def lower(value):
        with _UniffiRustBuffer.alloc_with_builder() as builder:
            builder.write(value.encode("utf-8"))
            return builder.finalize()

@dataclass
class CompactionMessage:
    """
    A text-only message. Compaction reads conversations as text, so this is the
    whole input shape callers need across the language boundary.
"""
    def __init__(self, *, role:MessageRole, text:str):
        self.role = role
        self.text = text
        
        

    
    def __str__(self):
        return "CompactionMessage(role={}, text={})".format(self.role, self.text)
    def __eq__(self, other):
        if self.role != other.role:
            return False
        if self.text != other.text:
            return False
        return True

class _UniffiFfiConverterTypeCompactionMessage(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        return CompactionMessage(
            role=_UniffiFfiConverterTypeMessageRole.read(buf),
            text=_UniffiFfiConverterString.read(buf),
        )

    @staticmethod
    def check_lower(value):
        _UniffiFfiConverterTypeMessageRole.check_lower(value.role)
        _UniffiFfiConverterString.check_lower(value.text)

    @staticmethod
    def write(value, buf):
        _UniffiFfiConverterTypeMessageRole.write(value.role, buf)
        _UniffiFfiConverterString.write(value.text, buf)

