class GooseStreamErrorKind(enum.Enum):
    
    RATE_LIMITED = 0
    
    OUTPUT_TOKEN_LIMIT_EXCEEDED = 1
    
    CONTEXT_LENGTH_EXCEEDED = 2
    
    AUTHENTICATION = 3
    
    TIMEOUT = 4
    
    PROVIDER_UNAVAILABLE = 5
    
    GENERIC = 6
    


class _UniffiFfiConverterTypeGooseStreamErrorKind(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return GooseStreamErrorKind.RATE_LIMITED
        if variant == 2:
            return GooseStreamErrorKind.OUTPUT_TOKEN_LIMIT_EXCEEDED
        if variant == 3:
            return GooseStreamErrorKind.CONTEXT_LENGTH_EXCEEDED
        if variant == 4:
            return GooseStreamErrorKind.AUTHENTICATION
        if variant == 5:
            return GooseStreamErrorKind.TIMEOUT
        if variant == 6:
            return GooseStreamErrorKind.PROVIDER_UNAVAILABLE
        if variant == 7:
            return GooseStreamErrorKind.GENERIC
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == GooseStreamErrorKind.RATE_LIMITED:
            return
        if value == GooseStreamErrorKind.OUTPUT_TOKEN_LIMIT_EXCEEDED:
            return
        if value == GooseStreamErrorKind.CONTEXT_LENGTH_EXCEEDED:
            return
        if value == GooseStreamErrorKind.AUTHENTICATION:
            return
        if value == GooseStreamErrorKind.TIMEOUT:
            return
        if value == GooseStreamErrorKind.PROVIDER_UNAVAILABLE:
            return
        if value == GooseStreamErrorKind.GENERIC:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == GooseStreamErrorKind.RATE_LIMITED:
            buf.write_i32(1)
        if value == GooseStreamErrorKind.OUTPUT_TOKEN_LIMIT_EXCEEDED:
            buf.write_i32(2)
        if value == GooseStreamErrorKind.CONTEXT_LENGTH_EXCEEDED:
            buf.write_i32(3)
        if value == GooseStreamErrorKind.AUTHENTICATION:
            buf.write_i32(4)
        if value == GooseStreamErrorKind.TIMEOUT:
            buf.write_i32(5)
        if value == GooseStreamErrorKind.PROVIDER_UNAVAILABLE:
            buf.write_i32(6)
        if value == GooseStreamErrorKind.GENERIC:
            buf.write_i32(7)



