@dataclass
class Usage:
    def __init__(self, *, input_tokens:typing.Optional[int], output_tokens:typing.Optional[int], total_tokens:typing.Optional[int], cache_read_input_tokens:typing.Optional[int], cache_creation_input_tokens:typing.Optional[int], reasoning_tokens:typing.Optional[int], model:str, provider_metadata_json:typing.Optional[str]):
        self.input_tokens = input_tokens
        self.output_tokens = output_tokens
        self.total_tokens = total_tokens
        self.cache_read_input_tokens = cache_read_input_tokens
        self.cache_creation_input_tokens = cache_creation_input_tokens
        self.reasoning_tokens = reasoning_tokens
        self.model = model
        self.provider_metadata_json = provider_metadata_json
        
        

    
    def __str__(self):
        return "Usage(input_tokens={}, output_tokens={}, total_tokens={}, cache_read_input_tokens={}, cache_creation_input_tokens={}, reasoning_tokens={}, model={}, provider_metadata_json={})".format(self.input_tokens, self.output_tokens, self.total_tokens, self.cache_read_input_tokens, self.cache_creation_input_tokens, self.reasoning_tokens, self.model, self.provider_metadata_json)
    def __eq__(self, other):
        if self.input_tokens != other.input_tokens:
            return False
        if self.output_tokens != other.output_tokens:
            return False
        if self.total_tokens != other.total_tokens:
            return False
        if self.cache_read_input_tokens != other.cache_read_input_tokens:
            return False
        if self.cache_creation_input_tokens != other.cache_creation_input_tokens:
            return False
        if self.reasoning_tokens != other.reasoning_tokens:
            return False
        if self.model != other.model:
            return False
        if self.provider_metadata_json != other.provider_metadata_json:
            return False
        return True

