# GooseError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class GooseError(Exception):
    pass

_UniffiTempGooseError = GooseError

class GooseError:  # type: ignore
    
    class RateLimited(_UniffiTempGooseError):
        
        def __init__(self, retry_after_ms, retry_after_suffix):
            super().__init__(", ".join([
                "retry_after_ms={!r}".format(retry_after_ms),
                "retry_after_suffix={!r}".format(retry_after_suffix),
            ]))
            self.retry_after_ms = retry_after_ms
            self.retry_after_suffix = retry_after_suffix

        def __repr__(self):
            return "GooseError.RateLimited({})".format(str(self))
    _UniffiTempGooseError.RateLimited = RateLimited # type: ignore
    class OutputTokenLimitExceeded(_UniffiTempGooseError):
        
        def __init__(self, details):
            super().__init__(", ".join([
                "details={!r}".format(details),
            ]))
            self.details = details

        def __repr__(self):
            return "GooseError.OutputTokenLimitExceeded({})".format(str(self))
    _UniffiTempGooseError.OutputTokenLimitExceeded = OutputTokenLimitExceeded # type: ignore
    class ContextLengthExceeded(_UniffiTempGooseError):
        
        def __init__(self, details):
            super().__init__(", ".join([
                "details={!r}".format(details),
            ]))
            self.details = details

        def __repr__(self):
            return "GooseError.ContextLengthExceeded({})".format(str(self))
    _UniffiTempGooseError.ContextLengthExceeded = ContextLengthExceeded # type: ignore
    class Authentication(_UniffiTempGooseError):
        
        def __init__(self, details):
            super().__init__(", ".join([
                "details={!r}".format(details),
            ]))
            self.details = details

        def __repr__(self):
            return "GooseError.Authentication({})".format(str(self))
    _UniffiTempGooseError.Authentication = Authentication # type: ignore
    class Timeout(_UniffiTempGooseError):
        
        def __init__(self, details):
            super().__init__(", ".join([
                "details={!r}".format(details),
            ]))
            self.details = details

        def __repr__(self):
            return "GooseError.Timeout({})".format(str(self))
    _UniffiTempGooseError.Timeout = Timeout # type: ignore
    class ProviderUnavailable(_UniffiTempGooseError):
        
        def __init__(self, details):
            super().__init__(", ".join([
                "details={!r}".format(details),
            ]))
            self.details = details

        def __repr__(self):
            return "GooseError.ProviderUnavailable({})".format(str(self))
    _UniffiTempGooseError.ProviderUnavailable = ProviderUnavailable # type: ignore
    class Generic(_UniffiTempGooseError):
        
        def __init__(self, details):
            super().__init__(", ".join([
                "details={!r}".format(details),
            ]))
            self.details = details

        def __repr__(self):
            return "GooseError.Generic({})".format(str(self))
    _UniffiTempGooseError.Generic = Generic # type: ignore

GooseError = _UniffiTempGooseError # type: ignore
del _UniffiTempGooseError


class _UniffiFfiConverterTypeGooseError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return GooseError.RateLimited(
                _UniffiFfiConverterOptionalUInt64.read(buf),
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 2:
            return GooseError.OutputTokenLimitExceeded(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 3:
            return GooseError.ContextLengthExceeded(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 4:
            return GooseError.Authentication(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 5:
            return GooseError.Timeout(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 6:
            return GooseError.ProviderUnavailable(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 7:
            return GooseError.Generic(
                _UniffiFfiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, GooseError.RateLimited):
            _UniffiFfiConverterOptionalUInt64.check_lower(value.retry_after_ms)
            _UniffiFfiConverterString.check_lower(value.retry_after_suffix)
            return
        if isinstance(value, GooseError.OutputTokenLimitExceeded):
            _UniffiFfiConverterString.check_lower(value.details)
            return
        if isinstance(value, GooseError.ContextLengthExceeded):
            _UniffiFfiConverterString.check_lower(value.details)
            return
        if isinstance(value, GooseError.Authentication):
            _UniffiFfiConverterString.check_lower(value.details)
